import heapq

def solve(nums, k):
    # Create a max-heap of size k
    heap = nums[:k]
    heapq._heapify_max(heap)

    for num in nums[k:]:
        if num < heap[0]:
            heapq._heappop_max(heap)
            heapq.heappush(heap, num)

    return heap[0]

